                for (let i = 0; i < this.fontSet.length; i++) {
                    this.memory[0x050 + i] = this.fontSet[i];
                }

                // Reset registers
                this.v.fill(0);
                this.i = 0;
                this.pc = 0x200;
                this.stackPointer = 0;
                this.stack.length = 0;

                // Reset timers
                this.delayTimer = 0;
                this.soundTimer = 0;

                // Clear display
                this.display.fill(0);

                // Reset keys
