                this.updateDebugger();
            },

            // Load a ROM file
            loadROM: function(romData) {
                // Clear memory
                this.memory.fill(0);

                // Load font set
                for (let i = 0; i < this.fontSet.length; i++) {
                    this.memory[0x050 + i] = this.fontSet[i];
                }

                // Load ROM data starting at 0x200
                for (let i = 0; i < romData.length; i++) {
                    this.memory[0x200 + i] = romData[i];
