            // Execute one instruction
            executeInstruction: function() {
                // Get current instruction (2 bytes)
                const highByte = this.memory[this.pc];
                const lowByte = this.memory[this.pc + 1];
                const instruction = (highByte << 8) | lowByte;

                // Update current instruction display
                document.getElementById('current-instruction').textContent = '0x' + instruction.toString(16).padStart(4, '0');

                // Extract parts of instruction
                const nnn = instruction & 0x0FFF;
                const n = instruction & 0x000F;
                const x = (instruction & 0x0F00) >> 8;
                const y = (instruction & 0x00F0) >> 4;
                const kk = instruction & 0x00FF;

                // Execute instruction
                switch (instruction & 0xF000) {
                    case 0x0000:
                        switch (instruction) {
                            case 0x00E0: // CLS - Clear the display
                                this.display.fill(0);
                                this.pc += 2;
                                break;
                            case 0x00EE: // RET - Return from subroutine
                                this.stackPointer--;
                                this.pc = this.stack[this.stackPointer];
                                break;
                            default:
                                // SYS addr - Not used in CHIP-8
                                this.pc += 2;
                                break;
                        }
                        break;

                    case 0x1000: // JP addr - Jump to location nnn
                        this.pc = nnn;
                        break;

                    case 0x2000: // CALL addr - Call subroutine at nnn
                        this.stack[this.stackPointer] = this.pc + 2;
                        this.stackPointer++;
                        this.pc = nnn;
                        break;

                    case 0x3000: // SE Vx, byte - Skip next instruction if Vx == kk
                        if (this.v[x] === kk) {
                            this.pc += 4;
                        } else {
                            this.pc += 2;
                        }
                        break;

                    case 0x4000: // SNE Vx, byte - Skip next instruction if Vx != kk
                        if (this.v[x] !== kk) {
                            this.pc += 4;
                        } else {
                            this.pc += 2;
                        }
                        break;

                    case 0x5000: // SE Vx, Vy - Skip next instruction if Vx == Vy
                        if (this.v[x] === this.v[y]) {
                            this.pc += 4;
                        } else {
                            this.pc += 2;
                        }
                        break;

                    case 0x6000: // LD Vx, byte - Set Vx = kk
                        this.v[x] = kk;
                        this.pc += 2;
                        break;

                    case 0x7000: // ADD Vx, byte - Set Vx = Vx + kk
                        this.v[x] = (this.v[x] + kk) & 0xFF;
                        this.pc += 2;
                        break;

                    case 0x8000:
                        switch (n) {
                            case 0x0: // LD Vx, Vy - Set Vx = Vy
                                this.v[x] = this.v[y];
                                this.pc += 2;
                                break;
                            case 0x1: // OR Vx, Vy - Set Vx = Vx OR Vy
                                this.v[x] |= this.v[y];
                                this.pc += 2;
                                break;
                            case 0x2: // AND Vx, Vy - Set Vx = Vx AND Vy
                                this.v[x] &= this.v[y];
                                this.pc += 2;
                                break;
                            case 0x3: // XOR Vx, Vy - Set Vx = Vx XOR Vy
                                this.v[x] ^= this.v[y];
                                this.pc += 2;
                                break;
                            case 0x4: // ADD Vx, Vy - Set Vx = Vx + Vy, set VF = carry
                                const sum = this.v[x] + this.v[y];
                                this.v[x] = sum & 0xFF;
                                this.v[0xF] = sum > 0xFF ? 1 : 0;
                                this.pc += 2;
                                break;
                            case 0x5: // SUB Vx, Vy - Set Vx = Vx - Vy, set VF = NOT borrow
                                this.v[0xF] = this.v[x] > this.v[y] ? 1 : 0;
                                this.v[x] = (this.v[x] - this.v[y]) & 0xFF;
                                this.pc += 2;
                                break;
                            case 0x6: // SHR Vx {, Vy} - Set Vx = Vx SHR 1
                                this.v[0xF] = this.v[x] & 1;
                                this.v[x] >>= 1;
                                this.pc += 2;
                                break;
                            case 0x7: // SUBN Vx, Vy - Set Vx = Vy - Vx, set VF = NOT borrow
                                this.v[0xF] = this.v[y] > this.v[x] ? 1 : 0;
                                this.v[x] = (this.v[y] - this.v[x]) & 0xFF;
                                this.pc += 2;
                                break;
                            case 0xE: // SHL Vx {, Vy} - Set Vx = Vx SHL 1
                                this.v[0xF] = (this.v[x] >> 7) & 1;
                                this.v[x] = (this.v[x] << 1) & 0xFF;
                                this.pc += 2;
                                break;
                            default:
                                this.pc += 2;
                                break;
                        }
                        break;

                    case 0x9000: // SNE Vx, Vy - Skip next instruction if Vx != Vy
                        if (this.v[x] !== this.v[y]) {
                            this.pc += 4;
                        } else {
                            this.pc += 2;
                        }
                        break;

                    case 0xA000: // LD I, addr - Set I = nnn
                        this.i = nnn;
                        this.pc += 2;
                        break;

                    case 0xB000: // JP V0, addr - Jump to location nnn + V0
                        this.pc = nnn + this.v[0];
                        break;

                    case 0xC000: // RND Vx, byte - Set Vx = random byte AND kk
                        const random = Math.floor(Math.random() * 256);
                        this.v[x] = random & kk;
                        this.pc += 2;
                        break;

                    case 0xD000: // DRW Vx, Vy, nibble - Display sprite
                        const width = 8; // Sprite width is always 8 pixels
                        const height = n; // Height is given by the nibble

                        // Reset collision flag
                        this.v[0xF] = 0;

                        // Get sprite data from memory at index I
                        for (let row = 0; row < height; row++) {
                            const spriteByte = this.memory[this.i + row];

                            for (let col = 0; col < width; col++) {
                                // Check if pixel is set in sprite
                                const pixel = (spriteByte >> (7 - col)) & 1;

                                // Calculate display position
                                const xPixel = (this.v[x] + col) % 64;
                                const yPixel = (this.v[y] + row) % 32;
                                const index = yPixel * 64 + xPixel;

                                // XOR with existing pixel
                                if (pixel === 1) {
                                    if (this.display[index] === 1) {
                                        // Collision detected
                                        this.v[0xF] = 1;
                                    }
                                    this.display[index] ^= 1;
                                }
                            }
                        }

                        this.pc += 2;
                        break;

                    case 0xE000:
                        switch (kk) {
                            case 0x9E: // SKP Vx - Skip next instruction if key with value of Vx is pressed
                                if (this.keys[this.v[x]] === 1) {
                                    this.pc += 4;
                                } else {
                                    this.pc += 2;
                                }
                                break;
                            case 0xA1: // SKNP Vx - Skip next instruction if key with value of Vx is not pressed
                                if (this.keys[this.v[x]] === 0) {
                                    this.pc += 4;
                                } else {
                                    this.pc += 2;
                                }
                                break;
                            default:
                                this.pc += 2;
                                break;
                        }
                        break;

                    case 0xF000:
                        switch (kk) {
                            case 0x07: // LD Vx, DT - Set Vx = delay timer value
                                this.v[x] = this.delayTimer;
                                this.pc += 2;
                                break;
                            case 0x0A: // LD Vx, K - Wait for key press, store in Vx
                                // This will be handled in the input update function
                                // We'll pause execution until a key is pressed
                                this.pc += 2;
                                this.waitingForKey = x;
                                break;
                            case 0x15: // LD DT, Vx - Set delay timer = Vx
                                this.delayTimer = this.v[x];
                                this.pc += 2;
                                break;
                            case 0x18: // LD ST, Vx - Set sound timer = Vx
                                this.soundTimer = this.v[x];
                                this.pc += 2;
                                break;
                            case 0x1E: // ADD I, Vx - Set I = I + Vx
                                const iSum = this.i + this.v[x];
                                this.v[0xF] = iSum > 0xFFF ? 1 : 0;
                                this.i = iSum & 0xFFF;
                                this.pc += 2;
                                break;
                            case 0x29: // LD F, Vx - Set I = location of sprite for digit Vx
                                this.i = 0x050 + (this.v[x] * 5);
                                this.pc += 2;
                                break;
                            case 0x33: // LD B, Vx - Store BCD representation of Vx
                                this.memory[this.i] = Math.floor(this.v[x] / 100);
                                this.memory[this.i + 1] = Math.floor((this.v[x] / 10) % 10);
                                this.memory[this.i + 2] = this.v[x] % 10;
                                this.pc += 2;
                                break;
                            case 0x55: // LD [I], Vx - Store registers V0 through Vx in memory starting at I
                                for (let i = 0; i <= x; i++) {
                                    this.memory[this.i + i] = this.v[i];
                                }
