                                break;
                            case 0x65: // LD Vx, [I] - Read registers V0 through Vx from memory starting at I
                                for (let i = 0; i <= x; i++) {
                                    this.v[i] = this.memory[this.i + i];
                                }
                                this.pc += 2;
                                break;
                            default:
                                this.pc += 2;
                                break;
                        }
                        break;

                    default:
                        this.pc += 2;
                        break;
                }

                // Update debugger
                this.updateDebugger();
            },

            // Update the display
            updateDisplay: function() {
                const canvas = document.getElementById('display');
                const ctx = canvas.getContext('2d');
                const imageData = ctx.createImageData(64, 32);

                for (let i = 0; i < 64 * 32; i++) {
                    const pixel = this.display[i];
                    const index = i * 4;

                    if (pixel === 1) {
                        imageData.data[index] = 255;     // R
                        imageData.data[index + 1] = 255; // G
                        imageData.data[index + 2] = 255; // B
                        imageData.data[index + 3] = 255; // A
                    } else {
                        imageData.data[index] = 0;       // R
                        imageData.data[index + 1] = 0;   // G
                        imageData.data[index + 2] = 0;   // B
                        imageData.data[index + 3] = 255; // A
                    }
                }

                ctx.putImageData(imageData, 0, 0);
            },

            // Update the debugger display
            updateDebugger: function() {
                document.getElementById('pc').textContent = '0x' + this.pc.toString(16).padStart(3, '0');
                document.getElementById('i').textContent = '0x' + this.i.toString(16).padStart(3, '0');
                document.getElementById('dt').textContent = this.delayTimer;
                document.getElementById('st').textContent = this.soundTimer;

                for (let i = 0; i < 16; i++) {
                    const elementId = 'v' + (i === 10 ? 'A' : i === 11 ? 'B' : i === 12 ? 'C' : i === 13 ? 'D' : i === 14 ? 'E' : i === 15 ? 'F' : i);
                    document.getElementById(elementId).textContent = '0x' + this.v[i].toString(16).padStart(2, '0');
